interface RemovalDependencies {
  readonly rm: typeof rm;
  readonly unlink: typeof unlink;
  readonly validate: typeof assertSafeExistingTarget;
  readonly elevate: typeof runElevated;
}

const removalDependencies: RemovalDependencies = {
  rm,
  unlink,
  validate: assertSafeExistingTarget,
  elevate: runElevated,
};

type RemovalSnapshot = {
  readonly device: bigint;
  readonly inode: bigint;
  readonly kind: bigint;
  readonly isLink: boolean;
} | null;

async function removalSnapshot(target: string): Promise<RemovalSnapshot> {
  try {
    const stat = await lstat(target, { bigint: true });
    return {
      device: stat.dev,
      inode: stat.ino,
      kind: stat.mode & 0o170000n,
      isLink: stat.isSymbolicLink(),
    };
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
}

function assertUnchangedTarget(
  target: string,
  expected: RemovalSnapshot,
  current: RemovalSnapshot,
): void {
  // Disappearance is harmless; appearance or replacement is not authorized.
  if (current === null) return;
  if (
    expected === null ||
    expected.device !== current.device ||
    expected.inode !== current.inode ||
    expected.kind !== current.kind ||
    expected.isLink !== current.isLink
  ) {
    throw new Error(`Cleanup target changed after safety validation: '${target}'.`);
  }
}

async function validateRemovalSnapshot(
  target: string,
  allowedParents: readonly string[],
  context: RuntimeContext,
  dependencies: RemovalDependencies,
  expected: RemovalSnapshot,
): Promise<RemovalSnapshot> {
  assertUnchangedTarget(target, expected, await removalSnapshot(target));
  await dependencies.validate(target, allowedParents, context);
  const current = await removalSnapshot(target);
  assertUnchangedTarget(target, expected, current);
  return current;
}

async function captureRemovalSnapshot(
  target: string,
  allowedParents: readonly string[],
  context: RuntimeContext,
  dependencies: RemovalDependencies,
): Promise<RemovalSnapshot> {
  const expected = await removalSnapshot(target);
  await validateRemovalSnapshot(target, allowedParents, context, dependencies, expected);
  return expected;
}

export interface RemovePathOptions {

  readonly coveredBy?: readonly ComponentId[];
  /** Injectable mutation boundaries; omitted in production. */
  readonly dependencies?: Partial<RemovalDependencies>;
}

export async function removePathTarget(
  target: string,
  allowedParents: readonly string[],
  context: RuntimeContext,
): Promise<OperationResult> {
  return await removeValidatedPathTarget(target, allowedParents, context, removalDependencies);
}

async function removeValidatedPathTarget(
  target: string,
  allowedParents: readonly string[],
  context: RuntimeContext,
  dependencies: RemovalDependencies,
  validated?: RemovalSnapshot,
): Promise<OperationResult> {
  try {
    const expected = validated === undefined
      ? await captureRemovalSnapshot(target, allowedParents, context, dependencies)
      : validated;
    const immediate = await validateRemovalSnapshot(
      target, allowedParents, context, dependencies, expected,
    );
    if (immediate === null) return { status: "not-found" };

    try {
      if (immediate.isLink) {
        // Remove only the final link, never its destination.
        await dependencies.unlink(target);
      } else {
        await dependencies.rm(target, {
          recursive: true,
          force: true,
          maxRetries: 3,
          retryDelay: 100,
        });
      }
    } catch (nodeError) {
      if (context.platform === "windows") throw nodeError;
      // Keep the original identity even if Node partially removed the tree.
      const retryTarget = await validateRemovalSnapshot(
        target, allowedParents, context, dependencies, expected,
      );
      if (retryTarget === null) return { status: "removed" };
      const result = await dependencies.elevate(
        context,
        "/bin/rm",
        [retryTarget.isLink ? "-f" : "-rf", "--", target],
        { silent: true, timeoutMs: 10 * 60_000 },
      );
      if (result.exitCode !== 0) {
        return {
          status: "failed",
          detail: result.stderr.trim() ||
            (nodeError instanceof Error ? nodeError.message : String(nodeError)),
        };
      }
    }

    // A successful return is not proof of removal. Never retry this check:
    // anything still present could be a replacement.
    if (await removalSnapshot(target) !== null) {
      return { status: "failed", detail: `Cleanup target remains after removal: '${target}'.` };
    }
    return { status: "removed" };
  } catch (error) {
    return {
      status: "failed",
      detail: error instanceof Error ? error.message : String(error),
    };
  }
}

