test("filesystem removal preserves replacements and verifies remover results", async () => {
  const fs = await import("node:fs/promises");
  const safety = await import("../src/safety.js");
  type Dependencies = NonNullable<Parameters<typeof createRemovePathOperation>[0]["dependencies"]>;
  const root = await mkdtemp(join(tmpdir(), "maximize-space-removal-"));
  let sequence = 0;
  try {
    const fixture = async (dependencies: Dependencies = {}) => {
      const parent = join(root, String(sequence++));
      await fs.mkdir(parent);
      const target = join(parent, "target");
      await fs.mkdir(target);
      await fs.writeFile(join(target, "sentinel"), "original");
      const operation = createRemovePathOperation({
        id: `fixture:${sequence}`,
        component: "vcpkg",
        description: "disposable removal fixture",
        target,
        allowedParents: [parent],
        context: { ...contextFor("linux"), temp: join(root, "runner-temp"), workspace: undefined },
        dependencies: {
          elevate: async () => { throw new Error("unexpected privilege"); },
          ...dependencies,
        },
      });
      return { target, operation };
    };
    const replace = async (target: string) => {
      await fs.rename(target, `${target}-original`);
      await fs.mkdir(target);
      await fs.writeFile(join(target, "sentinel"), "replacement");
    };

    for (const kind of ["directory", "link", "appearance"] as const) {
      const { target, operation } = await fixture();
      if (kind === "appearance") await fs.rename(target, `${target}-original`);
      await operation.validate!();
      if (kind === "directory") await replace(target);
      if (kind === "link") {
        await fs.rename(target, `${target}-original`);
        await fs.symlink(`${target}-original`, target, "junction");
      }
      if (kind === "appearance") {
        await fs.mkdir(target);
        await fs.writeFile(join(target, "sentinel"), "replacement");
      }
      const result = await operation.run();
      assert.equal(result.status, "failed", kind);
      assert.match(result.detail ?? "", /changed after safety validation/);
      assert.equal(await fs.readFile(join(target, "sentinel"), "utf8"), kind === "link" ? "original" : "replacement");
    }

    let elevated = 0;
    const neverElevate: NonNullable<Dependencies["elevate"]> = async () => {
      elevated += 1;
      throw new Error("unexpected privilege");
    };
    const duringValidation = await fixture({
      validate: async (target, parents, context) => {
        await safety.assertSafeExistingTarget(target, parents, context);
        await replace(target);
      },
      elevate: neverElevate,
    });
    assert.equal((await duringValidation.operation.run()).status, "failed");
    assert.equal(await fs.readFile(join(duringValidation.target, "sentinel"), "utf8"), "replacement");

    const afterFailure = await fixture({
      rm: async (target) => {
        await replace(String(target));
        throw new Error("Node failure");
      },
      elevate: neverElevate,
    });
    assert.equal((await afterFailure.operation.run()).status, "failed");
    assert.equal(await fs.readFile(join(afterFailure.target, "sentinel"), "utf8"), "replacement");

    for (const link of [false, true]) {
      const noOp = await fixture({ rm: async () => {}, unlink: async () => {}, elevate: neverElevate });
      if (link) {
        await fs.rename(noOp.target, `${noOp.target}-original`);
        await fs.symlink(`${noOp.target}-missing`, noOp.target);
      }
      const result = await noOp.operation.run();
      assert.equal(result.status, "failed");
      assert.match(result.detail ?? "", /remains after removal/);
    }
    assert.equal(elevated, 0);

    const vanished = await fixture({
      rm: async (target) => {
        await fs.rm(target, { recursive: true });
        throw new Error("late Node failure");
      },
      elevate: neverElevate,
    });
    assert.equal((await vanished.operation.run()).status, "removed");
    assert.equal(elevated, 0);

    for (const outcome of ["removed", "remaining", "rejected", "nonzero"] as const) {
      let retries = 0;
      const retry = await fixture({
        rm: async () => { throw new Error("Node denied"); },
        elevate: async (_context, command, args, options) => {
          retries += 1;
          assert.equal(command, "/bin/rm");
          assert.deepEqual(args, ["-rf", "--", retry.target]);
          assert.deepEqual(options, { silent: true, timeoutMs: 10 * 60_000 });
          if (outcome === "rejected") throw new Error("privilege rejected");
          if (outcome === "removed") await fs.rm(retry.target, { recursive: true });
          return { exitCode: outcome === "nonzero" ? 1 : 0, stdout: "", stderr: "privileged failure" };
        },
      });
      const result = await retry.operation.run();
      assert.equal(result.status, outcome === "removed" ? "removed" : "failed");
      assert.equal(retries, 1);
      if (outcome === "nonzero") assert.equal(result.detail, "privileged failure");
    }

    const missing = await fixture();
    await fs.rm(missing.target, { recursive: true });
    await missing.operation.validate!();
    assert.equal((await missing.operation.run()).status, "not-found");
    const disappearing = await fixture();
    await disappearing.operation.validate!();
    await fs.rm(disappearing.target, { recursive: true });
    assert.equal((await disappearing.operation.run()).status, "not-found");

    // Replace during the package phase, after complete-plan validation.
    const changed = await fixture();
    const ordinary = await fixture();
    const mutation = createFunctionOperation({
      id: "replace-fixture",
      component: "vcpkg",
      description: "replace disposable fixture",
      phase: "package",
      run: async () => {
        await replace(changed.target);
        return { status: "removed" };
      },
    });
    const results = await executeOperations([mutation, changed.operation, ordinary.operation]);
    assert.deepEqual(results.map(({ status }) => status), ["removed", "failed", "removed"]);
    assert.equal(results.filter(({ status }) => status === "failed").length, 1);
    assert.equal(await fs.readFile(join(changed.target, "sentinel"), "utf8"), "replacement");
    await assert.rejects(fs.lstat(ordinary.target), { code: "ENOENT" });
  } finally {
    await fs.rm(root, { recursive: true, force: true });
  }
});

