test("managed-directory cleanup rejects a root replaced by its uninstaller and continues", async () => {
  const { createFunctionOperation, executeOperations } = await import("../src/operations.js");
  // Entirely virtual disposable fixture: no host installation is inspected.
  const root = "C:\\Program Files\\Miniconda3";
  const executable = `${root}\\Uninstall-Miniconda3.exe`;
  let replaced = false;
  let executions = 0;
  let continued = false;
  const probe: WindowsPathProbe = {
    lstat: async (path) => {
      assert.ok(path === root || path === executable);
      return windowsPathStats(path === root ? "directory" : "file", {
        ino: path === root && replaced ? 99n : 3n,
      });
    },
  };
  const operation = managedDirectoryUninstallOperation({
    context: contextFor("windows"),
    component: "miniconda",
    id: "replaced-root-test",
    description: "virtual Miniconda fixture",
    target: root,
    uninstaller: "Uninstall-Miniconda3.exe",
    args: ["/S"],
    probe,
    execute: async () => {
      executions += 1;
      replaced = true;
      return { exitCode: 0, stdout: "", stderr: "" };
    },
  });
  const other = createFunctionOperation({
    id: "after-replaced-root",
    component: "miniconda",
    description: "independent mocked operation",
    phase: "package",
    run: async () => {
      continued = true;
      return { status: "removed" };
    },
  });
  const results = await executeOperations([operation, other]);
  assert.deepEqual(results.map(({ status }) => status), ["failed", "removed"]);
  assert.match(results[0]?.detail ?? "", /root changed after uninstaller execution/);
  assert.equal(executions, 1);
  assert.equal(continued, true);
  assert.equal((await probe.lstat(root)).ino, 99n);
});

